 it('denies initial context-authorization mutation before any quote read',async()=>{const f=bookingFixture();f.options.authorizeContext=async()=>{f.c.input.authorizationScope.ownerRef='foreign';return true;};await expect(packet(f)).rejects.toThrow('booking_context_changed');expect(f.quoteCalls).toHaveLength(0);});
 it('uses exact original attachment guest proofs and keeps their independent authorizer',async()=>{const f=bookingFixture(),read=f.options.readBookingPrerequisites;f.c.facts[3].source={...f.c.facts[3].source,attachmentId:'original-guest-pdf',sourceHash:'e'.repeat(64)};let attachmentAuthorized=0;f.options.readBookingPrerequisites=async(...args:any[])=>{const p=await read(...args),revision=args[1];p.guestFacts=[{sourceRef:'original-guest-pdf',sourceHash:'e'.repeat(64),authorizationId:revision.authorizationId,propertyCode:revision.propertyCode,scopeDigest:revision.scopeDigest,observedAt:f.c.input.clock.causalAt,factRef:'guest',groupId:'g',roomIndex:1,firstName:'Alex',lastName:'Example'}];p.authorizeSource=async(proof:any)=>{if(proof.sourceRef==='original-guest-pdf')attachmentAuthorized++;return true;};return p;};expect((await packet(f)).packet.status).toBe('pending_pms_action');expect(attachmentAuthorized).toBe(1);});
 it('does not manufacture an original attachment guest proof from the current clock',async()=>{const f=bookingFixture();f.c.facts[3].source={...f.c.facts[3].source,attachmentId:'original-guest-pdf',sourceHash:'e'.repeat(64)};await expect(packet(f)).rejects.toThrow('booking_guest_source_unavailable');});
 it('preserves more than one explicitly assigned physical room without reusing guests',async()=>{const f=bookingFixture();f.c.facts[1].value.quantity=2;f.c.facts.push({...f.c.facts[3],id:'guest2',value:{...f.c.facts[3].value,firstName:'Taylor',roomIndex:2}});expect((await packet(f)).packet).toMatchObject({status:'pending_pms_action',totalMinor:40000,rooms:[{roomIndex:1,guests:[{firstName:'Alex'}]},{roomIndex:2,guests:[{firstName:'Taylor'}]}]});});
 it('does not alias a native room code to an original physical allocation ID',async()=>{const f=bookingFixture();f.c.facts[3].value.roomRef='STQN';await expect(packet(f)).rejects.toThrow('guest_assignment');});
 it('advances the source-evaluation clock after the completed prerequisite read',async()=>{const f=bookingFixture(),read=f.options.readBookingPrerequisites;let now=Date.parse(f.c.input.clock.sourceAt),evaluations=0;f.c.evaluateSourceAt=()=>{evaluations++;f.c.input.clock.sourceAt=new Date(now).toISOString();return f.c.input.clock.sourceAt;};f.options.readBookingPrerequisites=async(...args:any[])=>{const p=await read(...args);now+=1000;for(const field of ['availability','duplicates','codes','authorizedFields'])p[field].observedAt=new Date(now).toISOString();return p;};expect((await packet(f)).packet.status).toBe('pending_pms_action');expect(evaluations).toBeGreaterThan(0);});
 it('retains duplicate and inventory denial in the actual packet validator',async()=>{for(const kind of ['duplicate','inventory']){const f=bookingFixture(),read=f.options.readBookingPrerequisites;f.options.readBookingPrerequisites=async(...args:any[])=>{const p=await read(...args);if(kind==='duplicate')p.duplicates.matches=['existing'];else p.availability.available=false;return p;};expect((await packet(f)).packet).toMatchObject({status:'blocked',saved:false,rooms:[],businessRulesValidated:false});}});
